import XCTest
#if canImport(CryptoKit)
import CryptoKit
#else
import Crypto
#endif
@testable import Blindbandit

/// Byte-exact checks against vectors/p256-v1.json (generated by scripts/gen_p256_vectors.py with pyca/cryptography).
final class E2EEVectorTests: XCTestCase {
    struct FixedRandomness: E2EERandomness {
        let ek: P256.KeyAgreement.PrivateKey
        let cek: Data
        let nonces: [Data]
        let counter = Counter()
        final class Counter { var i = 0 }
        func ephemeralKey() -> P256.KeyAgreement.PrivateKey { ek }
        func contentKey() -> Data { cek }
        func nonce() -> Data { defer { counter.i += 1 }; return nonces[min(counter.i, nonces.count - 1)] }
    }

    var v: [String: Any] = [:]

    override func setUpWithError() throws {
        let url = Bundle(for: E2EEVectorTests.self).url(forResource: "p256-v1", withExtension: "json")
            ?? URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("vectors/p256-v1.json")
        v = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    private func dict(_ path: String...) -> [String: Any] {
        var cur: Any = v
        for p in path { cur = (cur as? [String: Any])?[p] as Any }
        return cur as? [String: Any] ?? [:]
    }
    private func str(_ d: [String: Any], _ k: String) -> String { d[k] as? String ?? "" }

    private func identity(_ who: String) throws -> E2EELocalIdentity {
        let k = dict("keys", who)
        return E2EELocalIdentity(deviceID: str(k, "device_id"), handle: str(k, "handle"),
                                 sign: try E2EECrypto.signingKey(hex: str(k, "sign_priv_hex")),
                                 dh: try E2EECrypto.agreementKey(hex: str(k, "dh_priv_hex")))
    }

    private func bobBundle() throws -> E2EEDeviceBundle {
        let b = dict("keys", "bob")
        return E2EEDeviceBundle(device_id: str(b, "device_id"), platform: "android", suite: "p256-v1",
                                identity_sign_pub: str(b, "sign_pub"), identity_dh_pub: str(b, "dh_pub"), device_cert: nil,
                                signed_prekey: E2EESignedPrekey(id: b["spk_id"] as? Int ?? 0, pub: str(b, "spk_pub"), sig: str(b, "spk_sig")),
                                prekey: E2EEOneTimePrekey(id: b["opk_id"] as? Int ?? 0, pub: str(b, "opk_pub")), handle: "bob")
    }

    private func bobStorage() throws -> InMemoryE2EEStorage {
        let b = dict("keys", "bob")
        let s = InMemoryE2EEStorage()
        s.spks[b["spk_id"] as? Int ?? 0] = try E2EECrypto.agreementKey(hex: str(b, "spk_priv_hex"))
        s.opks[b["opk_id"] as? Int ?? 0] = try E2EECrypto.agreementKey(hex: str(b, "opk_priv_hex"))
        return s
    }

    func testPublicKeysMatchVectors() throws {
        let a = try identity("alice"), b = try identity("bob")
        XCTAssertEqual(E2EECrypto.b64u(a.signPub), str(dict("keys", "alice"), "sign_pub"))
        XCTAssertEqual(E2EECrypto.b64u(a.dhPub), str(dict("keys", "alice"), "dh_pub"))
        XCTAssertEqual(E2EECrypto.b64u(b.dhPub), str(dict("keys", "bob"), "dh_pub"))
    }

    func testHKDFRFC5869Case1() {
        let c = dict("hkdf_rfc5869_case1")
        let okm = E2EECrypto.hkdf(E2EECrypto.unhex(str(c, "ikm_hex")), salt: E2EECrypto.unhex(str(c, "salt_hex")),
                                  info: E2EECrypto.unhex(str(c, "info_hex")), count: 42)
        XCTAssertEqual(E2EECrypto.hex(okm), str(c, "okm_hex"))
    }

    func testSignedPrekeySignatureVerifies() throws {
        XCTAssertNoThrow(try X3DH.verifyBundle(try bobBundle()))
        var tampered = try bobBundle()
        tampered.signed_prekey?.pub = str(dict("keys", "alice"), "dh_pub")
        XCTAssertThrowsError(try X3DH.verifyBundle(tampered))
    }

    func testX3DHBothSidesMatchVector() throws {
        let a = try identity("alice"), b = try identity("bob")
        let ek = try E2EECrypto.agreementKey(hex: str(dict("keys", "alice"), "ek_priv_hex"))
        let x = try X3DH.initiate(local: a, bundle: try bobBundle(), ephemeral: ek)
        XCTAssertEqual(E2EECrypto.b64u(x.sk), str(dict("x3dh"), "sk"))
        let s = try bobStorage()
        let sk = try X3DH.respond(local: b, senderDeviceID: a.deviceID, header: x.header, spk: s.spks[17]!, opk: s.opks[433])
        XCTAssertEqual(E2EECrypto.b64u(sk), str(dict("x3dh"), "sk"))
        var noOPK = try bobBundle(); noOPK.prekey = nil
        XCTAssertEqual(E2EECrypto.b64u(try X3DH.initiate(local: a, bundle: noOPK, ephemeral: ek).sk), str(dict("x3dh"), "sk_without_opk"))
    }

    func testChainMatchesVector() throws {
        let chain = v["chain"] as? [[String: Any]] ?? []
        var ck = try E2EECrypto.unb64u(str(chain[0], "ck"))
        for entry in chain {
            XCTAssertEqual(E2EECrypto.b64u(ck), str(entry, "ck"))
            let s = ChainRatchet.step(ck)
            XCTAssertEqual(E2EECrypto.b64u(s.mk), str(entry, "mk"))
            ck = s.next
        }
    }

    func testPaddingTables() throws {
        for row in v["padding"] as? [[String: Any]] ?? [] {
            let n = row["len"] as? Int ?? -1
            let padded = E2EECrypto.pad(Data(repeating: 0x41, count: n))
            XCTAssertEqual(padded.count, row["padded_len"] as? Int, "len \(n)")
            XCTAssertEqual(try E2EECrypto.unpad(padded).count, n)
        }
        for row in v["padme"] as? [[String: Any]] ?? [] {
            XCTAssertEqual(E2EECrypto.padme(row["len"] as? Int ?? 0), row["padded_len"] as? Int)
        }
        XCTAssertThrowsError(try E2EECrypto.unpad(Data(count: 16)))
    }

    func testEncryptReproducesVectorEnvelope() throws {
        let m = dict("message")
        let expected = try XCTUnwrap(E2EEEnvelope.from(any: m["envelope"]))
        let rand = FixedRandomness(ek: try E2EECrypto.agreementKey(hex: str(dict("keys", "alice"), "ek_priv_hex")),
                                   cek: try E2EECrypto.unb64u(str(m, "cek")),
                                   nonces: [try E2EECrypto.unb64u(str(m, "content_nonce")), try E2EECrypto.unb64u(str(m, "wrap_nonce"))])
        let env = try MessageCrypto.encrypt(E2EEPayload(t: "text"), msgID: str(m, "msg_id"), local: try identity("alice"),
                                            recipients: [try bobBundle()], storage: InMemoryE2EEStorage(), randomness: rand,
                                            payloadJSON: Data(str(m, "payload_json").utf8))
        XCTAssertEqual(env, expected)
    }

    func testBobDecryptsVectorEnvelopeAndReplayIsRejected() throws {
        let m = dict("message")
        let env = try XCTUnwrap(E2EEEnvelope.from(any: m["envelope"]))
        let storage = try bobStorage()
        let out = try MessageCrypto.decrypt(env, local: try identity("bob"), storage: storage)
        XCTAssertEqual(out.payload.body, "Hello Bob, this is encrypted.")
        XCTAssertEqual(out.payload.t, "text")
        XCTAssertNil(storage.opks[433], "one-time prekey must be consumed")
        XCTAssertThrowsError(try MessageCrypto.decrypt(env, local: try identity("bob"), storage: storage))
    }

    func testSafetyNumberMatchesVector() throws {
        let sn = dict("safety_number")
        let a = try identity("alice"), b = try identity("bob")
        XCTAssertEqual(E2EECrypto.hex(SafetyNumber.fingerprint(signPubs: [a.signPub], handle: "alice")), str(sn, "alice_fp_hex"))
        let fromBob = SafetyNumber(myHandle: "bob", mySignPubs: [b.signPub], theirHandle: "alice", theirSignPubs: [a.signPub])
        let fromAlice = SafetyNumber(myHandle: "alice", mySignPubs: [a.signPub], theirHandle: "bob", theirSignPubs: [b.signPub])
        XCTAssertEqual(fromBob.display, str(sn, "display"))
        XCTAssertEqual(fromAlice.qrPayload, str(sn, "qr"))
        XCTAssertTrue(fromBob.matches(scanned: fromAlice.qrPayload))
        XCTAssertEqual(fromBob.spokenGroup(0), "Group 1 of 12: 2 7 4 5 2")
    }

    func testAttachmentMatchesVector() throws {
        let at = dict("attachment")
        let n = at["plain_len"] as? Int ?? 0
        let plain = Data((0..<n).map { UInt8(($0 * 7) % 256) })
        let sealed = try AttachmentCrypto.seal(plain, key: try E2EECrypto.unb64u(str(at, "key")), baseNonce: try E2EECrypto.unb64u(str(at, "base_nonce")))
        XCTAssertEqual(sealed.blob.count, at["blob_len"] as? Int)
        XCTAssertEqual(E2EECrypto.hex(sealed.sha256), str(at, "sha256_hex"))
        let opened = try AttachmentCrypto.open(sealed.blob, key: sealed.key, baseNonce: sealed.baseNonce, plainSize: n, sha256: sealed.sha256)
        XCTAssertEqual(opened, plain)
        var bad = sealed.blob; bad[5] ^= 1
        XCTAssertThrowsError(try AttachmentCrypto.open(bad, key: sealed.key, baseNonce: sealed.baseNonce, plainSize: n, sha256: nil))
    }
}

/// Round trips with fresh random keys: multi-device fan-out, out-of-order delivery, tampering, unsend signature.
final class E2EERoundTripTests: XCTestCase {
    final class Device {
        let id: E2EELocalIdentity
        let storage = InMemoryE2EEStorage()
        let spk = P256.KeyAgreement.PrivateKey()
        let opk = P256.KeyAgreement.PrivateKey()
        init(handle: String, device: String) {
            id = E2EELocalIdentity(deviceID: device, handle: handle, sign: P256.Signing.PrivateKey(), dh: P256.KeyAgreement.PrivateKey())
            storage.spks[1] = spk; storage.opks[9] = opk
        }
        func bundle(withOPK: Bool = true) throws -> E2EEDeviceBundle {
            E2EEDeviceBundle(device_id: id.deviceID, platform: "ios", suite: "p256-v1", identity_sign_pub: E2EECrypto.b64u(id.signPub),
                             identity_dh_pub: E2EECrypto.b64u(id.dhPub), device_cert: nil,
                             signed_prekey: E2EESignedPrekey(id: 1, pub: E2EECrypto.b64u(spk.publicKey.x963Representation),
                                                             sig: E2EECrypto.b64u(try E2EECrypto.sign(spk.publicKey.x963Representation, with: id.sign))),
                             prekey: withOPK ? E2EEOneTimePrekey(id: 9, pub: E2EECrypto.b64u(opk.publicKey.x963Representation)) : nil, handle: id.handle)
        }
    }

    func testFanOutToTwoDevicesAndOutOfOrder() throws {
        let alice = Device(handle: "alice", device: "a1"), bob1 = Device(handle: "bob", device: "b1"), bob2 = Device(handle: "bob", device: "b2")
        let recipients = [try bob1.bundle(), try bob2.bundle(withOPK: false)]
        let e1 = try MessageCrypto.encrypt(E2EEPayload(t: "text", body: "one"), local: alice.id, recipients: recipients, storage: alice.storage)
        let e2 = try MessageCrypto.encrypt(E2EEPayload(t: "text", body: "two"), local: alice.id, recipients: recipients, storage: alice.storage)
        XCTAssertEqual(e1.keys.count, 2)
        XCTAssertEqual(try MessageCrypto.decrypt(e2, local: bob1.id, storage: bob1.storage).payload.body, "two")
        XCTAssertEqual(try MessageCrypto.decrypt(e1, local: bob1.id, storage: bob1.storage).payload.body, "one")
        XCTAssertEqual(try MessageCrypto.decrypt(e1, local: bob2.id, storage: bob2.storage).payload.body, "one")
        XCTAssertEqual(try MessageCrypto.decrypt(e2, local: bob2.id, storage: bob2.storage).payload.body, "two")
    }

    func testTamperedCiphertextAndWrongDeviceFail() throws {
        let alice = Device(handle: "alice", device: "a1"), bob = Device(handle: "bob", device: "b1"), eve = Device(handle: "eve", device: "e1")
        var env = try MessageCrypto.encrypt(E2EEPayload(t: "text", body: "secret"), local: alice.id, recipients: [try bob.bundle()], storage: alice.storage)
        XCTAssertThrowsError(try MessageCrypto.decrypt(env, local: eve.id, storage: eve.storage))
        var ct = try E2EECrypto.unb64u(env.ciphertext); ct[0] ^= 0xff
        env.ciphertext = E2EECrypto.b64u(ct)
        XCTAssertThrowsError(try MessageCrypto.decrypt(env, local: bob.id, storage: bob.storage))
    }

    func testRekeyAfterHundredMessages() throws {
        let alice = Device(handle: "alice", device: "a1"), bob = Device(handle: "bob", device: "b1")
        let bundle = try bob.bundle(withOPK: false)
        var first = ""
        for i in 0...ChainRatchet.rekeyAfterMessages {
            let env = try MessageCrypto.encrypt(E2EEPayload(t: "text", body: "\(i)"), local: alice.id, recipients: [bundle], storage: alice.storage)
            if i == 0 { first = env.keys[0].prekey?.ek ?? "" }
            if i == ChainRatchet.rekeyAfterMessages { XCTAssertNotEqual(env.keys[0].prekey?.ek, first); XCTAssertEqual(env.keys[0].n, 0) }
        }
    }

    func testSignedDeleteVerifiesOnlyForSender() throws {
        let alice = Device(handle: "alice", device: "a1"), eve = Device(handle: "eve", device: "e1")
        let del = try MessageCrypto.deletePayload(target: "m1", local: alice.id)
        XCTAssertTrue(MessageCrypto.verifyDelete(del, senderSignPubs: [E2EECrypto.b64u(alice.id.signPub)]))
        XCTAssertFalse(MessageCrypto.verifyDelete(del, senderSignPubs: [E2EECrypto.b64u(eve.id.signPub)]))
        var forged = del; forged.target_msg_id = "m2"
        XCTAssertFalse(MessageCrypto.verifyDelete(forged, senderSignPubs: [E2EECrypto.b64u(alice.id.signPub)]))
    }

    func testEnvelopeCodingIsLenient() throws {
        let alice = Device(handle: "alice", device: "a1"), bob = Device(handle: "bob", device: "b1")
        let env = try MessageCrypto.encrypt(E2EEPayload(t: "text", body: "x"), local: alice.id, recipients: [try bob.bundle()], storage: alice.storage)
        let json = String(data: try JSONEncoder().encode(env), encoding: .utf8)!
        XCTAssertEqual(E2EEEnvelope.from(any: json), env)
        XCTAssertEqual(E2EEEnvelope.from(any: env.jsonObject), env)
        XCTAssertNil(E2EEEnvelope.from(any: "not json"))
        XCTAssertNil(E2EEEnvelope.from(any: nil))
    }
}
